/**
 * Zoom types — Sawaa Dashboard
 *
 * Every RESPONSE shape is derived from the committed OpenAPI snapshot
 * (`lib/types/api.generated.ts`, regenerated by `pnpm openapi:sync`), so a
 * backend response change becomes a type error here instead of drifting
 * silently. `test/unit/lib/platform-ops-type-contract.spec.ts` pins that.
 *
 * Credentials are write-only: the GET/PUT view carries only the two booleans
 * `configured` / `isActive`, and the test probe only `ok` + an optional
 * `error`. No client id, secret, account id or ciphertext is ever returned.
 */

import type { components, paths } from "@/lib/types/api.generated"

type Schemas = components["schemas"]

/* ─── Entities (derived from OpenAPI) ─── */

/** `GET` / `PUT /dashboard/integrations/zoom` (`ZoomConfigResponseDto`). */
export type ZoomConfigView = Schemas["ZoomConfigResponseDto"]

/** `POST /dashboard/integrations/zoom/test` (`ZoomTestResultDto`). */
export type TestZoomResult = Schemas["ZoomTestResultDto"]

/** `PUT` / `POST …/zoom/test` body (`UpsertZoomConfigDto`) — credentials go up only. */
export type UpsertZoomConfigInput = Schemas["UpsertZoomConfigDto"]

/**
 * Booking-level Zoom meeting state vocabulary. Not owned by these routes: the
 * field rides on every booking row (`zoomMeetingStatus` in the booking
 * schemas), so it is derived from the booking record rather than re-declared.
 */
export type ZoomMeetingStatus = NonNullable<
  Schemas["BookingRecordDto"]["zoomMeetingStatus"]
>

/**
 * `POST /dashboard/bookings/{id}/zoom/retry`. Documented by the bookings
 * controller, not this unit; derived from the operation's own response so the
 * shape cannot drift from the retry handler.
 */
export type RetryZoomMeetingResult = ApiJsonResponse<"/api/v1/dashboard/bookings/{id}/zoom/retry", "post">

type SuccessStatus = 200 | 201 | 202
type ApiJsonResponse<
  Path extends keyof paths,
  Method extends keyof paths[Path],
> = paths[Path][Method] extends { responses: infer Responses }
  ? Responses[Extract<keyof Responses, SuccessStatus>] extends {
      content: { "application/json": infer Body }
    }
    ? Body
    : never
  : never
